  for (let i = 0; i < 5; i++) {
    const invResult = createInvoice({
      customerId: customerIds[i],
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: i + 1 }],
    });
    invoices.push(issueInvoice(invResult.value, invoices.map(inv => inv.number).filter(Boolean)).value);
  }

  const result = vatSummary(invoices);

  // All invoices have 21% VAT items
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  assert.ok(result[0].base > 0);
  assert.ok(result[0].vat > 0);
});

test('vatSummary with all three VAT rates present', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 }, // 21% VAT
      { sku: 'PRINT-A4', qty: 100 }, // 9% VAT
      { sku: 'WORKSHOP-DAY', qty: 1 }, // 0% VAT
    ],
  });

  const inv = issueInvoice(invResult.value, []).value;
  const result = vatSummary([inv]);

  assert.equal(result.length, 3);
  // Sorted by rate descending
  assert.equal(result[0].rate, 21);
  assert.equal(result[1].rate, 9);
  assert.equal(result[2].rate, 0);
  // Each should have base and vat
  for (const item of result) {
    assert.ok(typeof item.base === 'number');
    assert.ok(typeof item.vat === 'number');
  }
});

